from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG = float('-inf')
        dp = [[NEG] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = 0

        for j in range(1, k + 1):
            best = NEG
            for i in range(1, n + 1):
                t = i - m
                if t >= 0 and dp[t][j - 1] != NEG:
                    cand = dp[t][j - 1] - prefix[t]
                    if cand > best:
                        best = cand

                dp[i][j] = dp[i - 1][j]
                if best != NEG:
                    val = best + prefix[i]
                    if val > dp[i][j]:
                        dp[i][j] = val

        return dp[n][k]
